def solve():
    # g[k][c] is the maximum number of Op (1) moves to produce 2^k with c cells
    # k goes from 0 to 40, c goes from 1 to 9
    g = [[0] * 10 for _ in range(41)]

    for c in range(1, 10):
        g[0][c] = 1

    for k in range(1, 41):
        g[k][1] = 1
        for c in range(2, 10):
            g[k][c] = g[k-1][c] + g[k-1][c-1]

    print(f"g(40, 9) = {g[40][9]}")
    print(f"Total moves = 2 * {g[40][9]} - 1")

solve()

